        raise ValueError('Input must be a string.')

    total_seconds = 0
    pattern = re.compile(r'(\d+)([dhms])')
    matches = pattern.findall(text.lower())

    if not matches and text.strip() != '0':
        raise ValueError(
            'Invalid duration format. Expected format like '2h30m' or '45s'.'
        )
    elif not matches and text.strip() == '0':
        return 0

    seen_units = set()
    for value_str, unit in matches:
        value = int(value_str)
        if unit in seen_units:
            raise ValueError(f'Duplicate unit '{unit}' found in duration string.')
        seen_units.add(unit)

        if unit == 'd':
            total_seconds += value * 24 * 3600
        elif unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds

