    '''
    A simple LRU cache decorator.

    Args:
        maxsize (int): The maximum number of items the cache can store.
    '''
    def decorator(func):
        cache = OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Create a tuple for the cache key, including sorted kwargs
            key = (args, tuple(sorted(kwargs.items())))

            if key in cache:
                # Move the accessed item to the end to mark it as most recently used
                value = cache.pop(key)
                cache[key] = value
