from functools import wraps

def lru_cache_decorator(maxsize):
    'Simple LRU cache decorator'
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError('maxsize must be a positive integer')

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Create a hashable key for the cache
            key = (args, frozenset(kwargs.items()))

            if key in cache:
                # Move the accessed item to the end to mark as recently used
                result = cache.pop(key)
                cache[key] = result
                return result
            else:
                # Call the original function
                result = func(*args, **kwargs)
                cache[key] = result

                # If cache exceeds maxsize, remove the least recently used item
                if len(cache) > maxsize:
                    cache.popitem(last=False) # popitem(last=False) removes the first (LRU) item
                return result
        return wrapper
