def parse_duration(text):
    'Parses a duration string (e.g., '2h30m', '45s') into total seconds.'
    if not isinstance(text, str):
        raise TypeError('Input must be a string.')

    if not text:
        raise ValueError('Input string cannot be empty.')

    total_seconds = 0
    # Regular expression to find numbers followed by h, m, or s
    matches = re.findall(r'(\d+)([hms])', text)

    if not matches:
        raise ValueError(
