def lru_cache_decorator(maxsize):
    'A simple LRU cache decorator.'
    def decorator(func):
        cache = OrderedDict()

        def wrapper(*args, **kwargs):
            # Create a unique key for the cache entry
            key = args + tuple(sorted(kwargs.items()))

            if key in cache:
                # Move the accessed item to the end to mark it as recently used
                value = cache.pop(key)
                cache[key] = value
                return value
            else:
                # Call the original function and store the result
                result = func(*args, **kwargs)
                cache[key] = result

                # If the cache exceeds maxsize, remove the least recently used item
                if len(cache) > maxsize:
                    cache.popitem(last=False) # popitem(last=False) removes the first (oldest) item
                return result
        return wrapper
    return decorator

