    if not isinstance(text, str):
        raise TypeError('Expected a string for duration, got ' + str(type(text)))

    total_seconds = 0
    pattern = re.compile(r'(\d+)([hms])')
    matches = pattern.findall(text)

    if not matches and text != '0':
        raise ValueError(
            'Invalid duration format. Expected something like '2h30m' or '45s'.'
        )
    elif text == '0':
        return 0

    seen_units = set()
    for value_str, unit in matches:
        value = int(value_str)
        if unit in seen_units:
            raise ValueError(f'Duplicate unit ' + unit + ' in duration string.')
        seen_units.add(unit)

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    if not matches and total_seconds == 0:
        raise ValueError(
            'Invalid duration format. Expected something like '2h30m' or '45s'.'
        )

    return total_seconds
