def humanize_bytes(n):
    'Formats a byte count as a readable string (e.g., '1.5 MB').'
    if n < 0:
        raise ValueError('Number of bytes cannot be negative.')

    for unit in ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB']:
        if n < 1024:
            if unit == 'Bytes':
                return f'{n} {unit}'
            return f'{n:.1f} {unit}'
        n /= 1024.0
    return f'{n:.1f} YB' # Should not be reached for typical byte counts
