    if not rows:
        return ''

    # Get all unique headers from all rows
    headers = sorted(list(set(key for row in rows for key in row.keys())))

    # Calculate maximum width for each column
    column_widths = {header: len(header) for header in headers}
    for row in rows:
        for header in headers:
            column_widths[header] = max(column_widths[header], len(str(row.get(header, ''))))

    # Build the header row
    header_line = []
    for header in headers:
        header_line.append(header.ljust(column_widths[header]))
    table_str = ' | '.join(header_line) + '\n'

    # Add a separator line
    separator_line = []
    for header in headers:
        separator_line.append('-' * column_widths[header])
    table_str += '-+-'.join(separator_line) + '\n'

    # Build the data rows
    for row in rows:
        data_line = []
        for header in headers:
            data_line.append(str(row.get(header, '')).ljust(column_widths[header]))
        table_str += ' | '.join(data_line) + '\n'

    return table_str.strip()
