import functools

def lru_cache_decorator(maxsize):
    'Simple LRU cache decorator'
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError('maxsize must be a positive integer')

    def decorator(func):
        cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Create a tuple from args and a frozenset from kwargs for hashable key
            key_args = tuple(args)
            key_kwargs = frozenset(kwargs.items())
            key = (key_args, key_kwargs)

            if key in cache:
                # Move the accessed item to the end to mark it as recently used
                cache.move_to_end(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                # If the cache exceeds maxsize, remove the least recently used item (the first one)
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result
        return wrapper
    return decorator

