def humanize_bytes(n):
    'Formats a byte count as a readable string like '1.5 MB'.'
    if n < 0:
        raise ValueError('n must be a non-negative number')

    if n < 1024:
        return f'{n} B'

    for unit in ['KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB']:
        n /= 1024
        if n < 1024:
            return f'{n:.1f} {unit}'

    return f'{n:.1f} YB' # Should not be reached for practical purposes
