def format_table(rows):
    if not rows:
        return ''

    headers = list(rows[0].keys())

    # Calculate maximum width for each column
    column_widths = {header: len(header) for header in headers}
    for row in rows:
        for header in headers:
            column_widths[header] = max(column_widths[header], len(str(row.get(header, ''))))

    # Build the header row
    header_row = ' | '.join(header.ljust(column_widths[header]) for header in headers)

    # Build the separator row
    separator_row = '-+-'.join('-' * column_widths[header] for header in headers)

    # Build the data rows
    data_rows = []
    for row in rows:
        formatted_row = []
        for header in headers:
            formatted_row.append(str(row.get(header, '')).ljust(column_widths[header]))
        data_rows.append(' | '.join(formatted_row))

    return '\n'.join([header_row, separator_row] + data_rows)
