import re

def parse_duration(text):
    'Parses a duration string (e.g., '2h30m', '45s') into seconds.'
    if not isinstance(text, str):
        raise TypeError('Expected a string for duration parsing.')

    total_seconds = 0
    pattern = re.compile(r'(\d+)([hms])')
    matches = pattern.findall(text)

    if not matches and text.strip() != '0':
        raise ValueError(
            f'Invalid duration format: '{text}'. '
            'Expected formats like '2h30m', '45s', '1h', etc.'
        )

    seen_units = set()
    for value_str, unit in matches:
        value = int(value_str)
        if unit in seen_units:
            raise ValueError(f'Duplicate unit '{unit}' in duration: '{text}'.')
        seen_units.add(unit)

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    # Handle cases like '0' which should be 0 seconds
    if text.strip() == '0' and not matches:
        return 0

    return total_seconds
