def parse_duration(text):
    'Parses strings like \'2h30m\' or \'45s\' into seconds.'
    total_seconds = 0
    remaining_text = text

    while remaining_text:
        import re
        match = re.match(r'(\d+)([hms])', remaining_text)
        if not match:
            raise ValueError(
                f'Invalid duration format: \'{text}\'. '
                'Expected format like \'2h30m\' or \'45s\'.'
            )

        value, unit = int(match.group(1)), match.group(2)

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value
        else:
            # This case should technically be caught by the regex, but as a safeguard
            raise ValueError(f'Unknown unit \'{unit}\' in \'{text}\'.')

        remaining_text = remaining_text[len(match.group(0)):]

    return total_seconds
